        mp_state.elapsed = 0;
        mp_output.realized_a_m2.x = 0.0;
        mp_output.realized_a_m2.y = 0.0;
        mp_output.realized_a_m2.z = 0.0;
        mp_output.torque_nm = adcs_vec3_cross(&mp_output.realized_a_m2, mp_input.field_body_t);
        mp_output.mode = MP_REVERSAL_WAIT;
        return;
    }

    // Enter Pulse
    mp_state.captured_a_m2 = current_quantized;
    mp_state.last_capture_a_m2 = current_quantized;
    mp_state.mode = MP_PULSE;
    mp_state.elapsed = 1;
    mp_state.thermal_cycles++;

    if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
        mp_output.realized_a_m2.x = 0.0;
        mp_output.realized_a_m2.y = 0.0;
        mp_output.realized_a_m2.z = 0.0;
