// 1. Handle Disable/Fault Entry
if (!mp_input.enable) {
    mp_state.mode = MP_FAULT;
    mp_output.realized_a_m2.x = 0.0;
    mp_output.realized_a_m2.y = 0.0;
    mp_output.realized_a_m2.z = 0.0;
    mp_output.torque_nm.x = 0.0;
    mp_output.torque_nm.y = 0.0;
    mp_output.torque_nm.z = 0.0;
    mp_output.mode = MP_FAULT;
    return;
}

// If transitioning from Fault/Disabled to Enabled, clear state
if (mp_state.mode == MP_FAULT) {
    mp_state.mode = MP_IDLE;
    mp_state.elapsed = 0;
    mp_state.thermal_cycles = 0;
    mp_state.recovery_count = 0;
    mp_state.captured_a_m2.x = 0;
    mp_state.captured_a_m2.y = 0;
    mp_state.captured_a_m2.z = 0;
    mp_state.last_capture_a_m2.x = 0;
    mp_state.last_capture_a_m2.y = 0;
    mp_state.last_capture_a_m2.z = 0;
}

// 2. Parameter Validation
int valid_params = 1;
if (!adcs_is_finite_vec3(mp_input.request_a_m2) || !adcs_is_finite_vec3(mp_input.field_body_t)) {
    valid_params = 0;
} else {
    double field_norm = adcs_vec3_norm(mp_input.field_body_t);
    if (field_norm <= 1e-12) valid_params = 0;
    if (mp_config.max_dipole_a_m2 <= 0.0) valid_params = 0;
    if (mp_config.start_fraction <= 0.0 || mp_config.start_fraction > 1.0) valid_params = 0;
    if (mp_config.stop_fraction <= 0.0 || mp_config.stop_fraction >= mp_config.start_fraction) valid_params = 0;
    if (mp_config.pulse_cycles < 1 || mp_config.pulse_cycles > 100) valid_params = 0;
    if (mp_config.cooldown_cycles < 1 || mp_config.cooldown_cycles > 100) valid_params = 0;
    if (mp_config.reversal_blank_cycles < 1 || mp_config.reversal_blank_cycles > 100) valid_params = 0;
    if (mp_config.max_thermal_cycles < 1 || mp_config.max_thermal_cycles > 100) valid_params = 0;
    if (mp_config.recovery_cycles < 1 || mp_config.recovery_cycles > 100) valid_params = 0;
}

if (!valid_params) {
    mp_state.mode = MP_FAULT;
    mp_output.realized_a_m2.x = 0.0;
    mp_output.realized_a_m2.y = 0.0;
    mp_output.realized_a_m2.z = 0.0;
    mp_output.torque_nm.x = 0.0;
    mp_output.torque_nm.y = 0.0;
    mp_output.torque_nm.z = 0.0;
    mp_output.mode = MP_FAULT;
