// 3. Inhibit Logic
if (mp_state.mode == MP_INHIBIT) {
    mp_output.realized_a_m2.x = 0.0;
    mp_output.realized_a_m2.y = 0.0;
    mp_output.realized_a_m2.z = 0.0;

    double stop_th = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
    int all_below_stop = 1;
    for (int i = 0; i < 3; i++) {
        if (fabs((&mp_input.request_a_m2->x)[i]) >= stop_th) {
            all_below_stop = 0;
            break;
        }
    }

    if (all_below_stop) {
        mp_state.recovery_count++;
        if (mp_state.recovery_count >= mp_config.recovery_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.thermal_cycles = 0;
            mp_state.recovery_count = 0;
            mp_state.elapsed = 0;
        }
    } else {
        mp_state.recovery_count = 0;
    }

    mp_output.torque_nm = adcs_vec3_cross(&mp_state.captured_a_m2, mp_input.field_body_t);
    mp_output.mode = MP_INHIBIT;
    return;
