// 4. Schmitt Quantization
double start_th = mp_config.start_fraction * mp_config.max_dipole_a_m2;
double stop_th = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
adcs_vec3_t current_quantized = {0, 0, 0};

for (int i = 0; i < 3; i++) {
    double req = (&mp_input.request_a_m2->x)[i];
    double last = (&mp_state.last_capture_a_m2.x)[i];
    double mag_req = fabs(req);

    if (last > 0) {
        if (mag_req >= stop_th) {
            if (i == 0) current_quantized.x = mp_config.max_dipole_a_m2;
            if (i == 1) current_quantized.y = mp_config.max_dipole_a_m2;
            if (i == 2) current_quantized.z = mp_config.max_dipole_a_m2;
        }
    } else if (last < 0) {
        if (mag_req >= stop_th) {
            if (i == 0) current_quantized.x = -mp_config.max_dipole_a_m2;
            if (i == 1) current_quantized.y = -mp_config.max_dipole_a_m2;
            if (i == 2) current_quantized.z = -mp_config.max_dipole_a_m2;
